// Hand-written query (NOT generated by sqlc).
//
// Global active task count for the dispatch-fairness guard in the autopilot
// scheduler. Prevents dispatch-storm by checking total queue depth before
// claiming due triggers.

package db

import (
	"context"
)

const countGlobalActiveTasks = `-- name: CountGlobalActiveTasks :one
SELECT count(*) FROM agent_task_queue
WHERE status IN ('queued', 'dispatched', 'running', 'waiting_local_directory')
`

// CountGlobalActiveTasks returns the total number of active tasks across ALL
// agents in the workspace — queued + dispatched + running + waiting. Used by
// the autopilot scheduler to decide whether to skip a tick when the queue is
// already saturated (dispatch fairness / storm prevention).
func (q *Queries) CountGlobalActiveTasks(ctx context.Context) (int64, error) {
	var count int64
	err := q.db.QueryRow(ctx, countGlobalActiveTasks).Scan(&count)
	return count, err
}
